type Row=Record<string,any>;
type Data={user:Row;mosques:Row[];mosque_id:string;circles:Row[];students:Row[];attendance:Row[];progress:Row[];staff:Row[];accounts?:Row[];activity:Row[];date:string};
const entityLabel=(kind?:string)=>ENTITY_KINDS[kind as EntityKind]||'مسجد';
const ROLES:Row={admin:'مدير المنصّة',primary:'المشرف الأساسي',supervisor:'مشرف',teacher:'مدرّس',student:'طالب'};
