 useEffect(()=>{if(new URLSearchParams(location.search).get('view')==='calendar')setPage('calendar');const params=new URLSearchParams(location.hash.slice(1)),key=params.get('setup');if(key){setSetupKey(key);history.replaceState(null,'',location.pathname+location.search)}api('auth/status').then(s=>{if(s.user){setMode('app');load()}else setMode(!s.initialized&&key?'setup':'login')}).catch(e=>{setError(e.message);setMode('login')})},[]);
 useEffect(()=>{if(mode==='app'&&data)load(mid,date)},[mid,date]);
 useEffect(()=>{setDraft({})},[data?.attendance,date]);
