 const nav=(admin?[['overview','إدارة المنصّة',LayoutDashboard],['calendar','التقويم والنشاطات',CalendarDays],['team','إدارة الحسابات',UserRoundCog]]:[['overview','نظرة عامة',LayoutDashboard],['calendar','التقويم والنشاطات',CalendarDays],['quran','المصحف الشريف',BookOpen],...(['primary','supervisor'].includes(user?.role)?[['support','التواصل مع إدارة المنصّة',UserRoundCog]]:[]),['race','سباق الاجتهاد',Trophy],['my-circles','حلقاتي',BookOpen],['students','الطلاب',Users],['circles','الحلقات',BookOpen],...(!teacher?[['team','فريق التعليم',UserRoundCog]]:[]),['attendance','الحضور والغياب',ClipboardCheck],['progress','الحفظ والمتابعة',GraduationCap],['reports','التقارير',TrendingUp],['about','من نحن',Info]]) as [string,string,any][];
 const navigate=(key:string)=>{setPage(key);setSearch('');setCircleFilter('');setAccountFilter('');setMenu(false);setNotifications(false)};
