 async function submit(e:FormEvent){e.preventDefault();if(!modal)return;setBusy(true);setFormError('');try{const {type,item}=modal;const routes:Row={student:'students',circle:'circles',user:'users',progress:'progress',mosque:'mosques',password:'auth/password'};const result=await api(routes[type],{...form,auto_credentials:type==='user'&&!item,mosque_id:type==='user'?form.mosque_id:mid},item&&type!=='progress'?'PATCH':'POST');if(result.credentials)setCredentials({...result.credentials,name:form.name,kind:type==='user'?'staff':'student',contact_mode:form.contact_mode});if(type==='mosque'&&!item){setMid(result.id);await load(result.id)}else await load();setModal(null);tell(type==='password'?'تم تغيير كلمة السر':'تم الحفظ بنجاح')}catch(e){setFormError((e as Error).message)}finally{setBusy(false)}}
