 {page==='overview'&&admin&&<><div className="page-heading"><div><span className="eyebrow">أهلًا {user!.name.split(' ')[0]}</span><h1>إدارة منصّة سِراج</h1><p>إدارة المساجد والمراكز والحسابات والصلاحيات، في مكان واحد.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>navigate('team')}><UserRoundCog size={16}/>إدارة الحسابات</button><button className="btn primary" onClick={()=>open('mosque')}><Plus size={16}/>إضافة مسجد أو مركز</button></div></div><HadithCard/><div className="stats-grid">{[[Landmark,'المساجد والمراكز',data.mosques.length,'جهات تعليمية على سِراج','sage'],[Users,'حسابات الجهات',(data.accounts||[]).filter(a=>a.role!=='admin').length,'المشرفون والمدرّسون','sand'],[ShieldCheck,'الحسابات الفعّالة',(data.accounts||[]).filter(a=>a.role!=='admin'&&a.active).length,'حسابات جاهزة للاستخدام','blue'],[CalendarDays,'النشاطات المشتركة',community.feed?.events.length??'—','إعلانات متاحة للمستخدمين','rose']].map(([Icon,label,value,hint,color]:any)=><article className="stat-card" key={label}><div><span className="stat-label">{label}</span><span className={'stat-icon '+color}><Icon size={20}/></span></div><strong>{typeof value==='number'?number(value):value}</strong><small>{hint}</small></article>)}</div><div className="community-home-link"><span><CalendarDays size={18}/>تقويم مشترك لكل مستخدمي سِراج<small>النشاطات والمناسبات في جميع المساجد والمراكز.</small></span><button className="text-button" onClick={()=>navigate('calendar')}>عرض التقويم<ArrowLeft size={15}/></button></div><div className="panel-heading platform-section-heading"><div><h2>المساجد والمراكز وحساباتها</h2><p>عيّن مشرفًا أساسيًا لكل مسجد أو مركز ليتولّى فريقه وطلابه.</p></div></div><div className="cards-grid">{data.mosques.map(m=><article className="mosque-card" key={m.id}><div className="mosque-card-icon"><MosqueLogo name={m.name} customLogo={m.logo} size={36}/></div><h2>{m.name}</h2><p>{m.city||'الموقع غير محدّد'}</p><span className="badge neutral">{number((data.accounts||[]).filter(a=>a.mosque_id===m.id).length)} حساب</span><footer><button className="text-button" onClick={()=>{setMid(m.id);navigate('team');setAccountFilter(m.id)}}>حسابات الجهة<ArrowLeft size={14}/></button><button className="text-button" onClick={()=>{setMid(m.id);navigate('settings');setForm({})}}>إعدادات الجهة<Settings size={14}/></button></footer></article>)}</div></>}
 {page==='overview'&&!admin&&<><div className="page-heading"><div><div className="eyebrow">أهلًا {user!.name.split(' ')[0]} <span className="hello-leaf"><Sparkles size={18} aria-hidden="true"/></span></div><h1>رعاية اليوم، أثر الغد.</h1><p>نظرة على رحلة التعلّم في {mosque?.name}.</p></div><div className="date-chip"><CalendarDays size={17}/>{dayLabel(dateNow(),true)}<span className="dot"/></div></div><HadithCard/><div className="community-home-link"><span><CalendarDays size={18}/>نشاطات المساجد والمراكز في مكان واحد<small>متاح لكل مستخدمي سِراج بعد الدخول، وبيانات كل جهة تبقى خاصة.</small></span><button className="text-button" onClick={()=>navigate('calendar')}>التقويم المشترك<ArrowLeft size={15}/></button></div><section className="welcome-banner"><div className="welcome-copy"><span className="banner-pill"><span className="dot"/>مساحةٌ تنمو بالعلم</span><h2>نُضيء طريق التعلّم،<br/>طالبًا بعد طالب.</h2><p>نظّم حلقاتك، وتابع التقدّم، واترك للرعاية وقتًا أكبر.</p><button className="btn cream" onClick={()=>navigate('circles')}>انتقل إلى الحلقات<ArrowLeft size={16}/></button></div><div className="banner-art" aria-hidden="true"><div className="banner-ring r1"/><div className="banner-ring r2"/><div className="banner-ring r3"/><div className="banner-book"><BookOpen strokeWidth={1} size={92}/></div><span className="art-star as1"><Sparkles size={23} aria-hidden="true"/></span><span className="art-star as2"><Sparkles size={12} aria-hidden="true"/></span><span className="art-dot"/><span className="art-caption">عِلْمٌ • رِعايَةٌ • أَثَرٌ</span></div></section><div className="stats-grid">{[[Users,'الطلاب المنتظمون',activeStudents.length,'طالب في رحلة التعلّم','sage'],[BookOpen,'الحلقات التعليمية',data.circles.length,'مساحات للعلم والتربية','sand'],[UserRoundCog,'فريق التعليم',data.staff.filter(s=>s.active).length,'مشرفون ومدرّسون','blue'],[ClipboardCheck,'الحضور المسجّل',todayAttendance.length?attendanceRate+'٪':'—',todayAttendance.length?'نسبة الحضور في السجل':'بانتظار تسجيل حضور اليوم','rose']].map(([Icon,label,value,hint,color]:any,i)=><article className="stat-card" key={label}><div><span className="stat-label">{label}</span><span className={'stat-icon '+color}><Icon size={20}/></span></div><strong>{typeof value==='number'?number(value):value}</strong><small>{i===3&&todayAttendance.length>0?<><span className="tiny-dot green-dot"/>{number(attended)} حاضر من {number(todayAttendance.length)} مسجّل</>:hint}</small></article>)}</div>
 {!teacher&&!data.students.length&&<section className="onboarding-card"><div><span className="eyebrow">لنبدأ بخطوة</span><h3>جهّز مساحة التعلّم لفريقك</h3><p>أضف الفريق، ثم الحلقات، ثم الطلاب.</p></div><div className="onboarding-steps">{[[data.staff.length>0,'١','إضافة فريق التعليم',()=>manager?open('user'):navigate('team')],[data.circles.length>0,'٢','إنشاء أول حلقة',()=>!teacher?open('circle'):navigate('circles')],[false,'٣','إضافة أول طالب',()=>open('student')]].map(([done,n,label,action]:any)=><button key={n} onClick={action} disabled={n==='١'&&!manager||n==='٢'&&teacher}><span className={done?'done':''}>{done?<Check size={16}/>:n}</span>{label}<ArrowUpLeft size={15}/></button>)}</div></section>}
 <div className="dashboard-columns"><section className="panel circles-panel"><div className="panel-heading"><div><h2>حلقات الجهة <span>{number(data.circles.length)}</span></h2><p>لكلّ حلقة مساحة، ولكلّ طالب اهتمام.</p></div><button className="text-button" onClick={()=>navigate('circles')}>عرض الكل<ArrowLeft size={15}/></button></div><div className="compact-circles">{data.circles.slice(0,3).map((c,i)=><button className="compact-circle" key={c.id} onClick={()=>{navigate('students');setCircleFilter(c.id)}}><span className={'circle-icon color-'+i%4}><BookOpen size={22}/></span><div><h3>{c.name}</h3><p>{c.teacher_name||'لم يُعيّن المدرّس بعد'}</p><small><Clock size={12}/>{c.schedule||'الموعد غير محدد'}</small></div><span className="circle-count"><strong>{number(data.students.filter(s=>(s.circle_id===c.id||s.circle_ids?.includes(c.id))&&s.status==='active').length)}</strong>طالب</span><ArrowUpLeft size={17}/></button>)}</div>{!data.circles.length&&<Empty title="هنا تبدأ الحلقات" body="أنشئ حلقة وحدّد مدرّسها وموعدها." action={manager&&<button className="btn secondary" onClick={()=>open('circle')}><Plus size={16}/>إنشاء حلقة</button>}/>}<button className="panel-bottom-button" onClick={()=>manager?open('circle'):navigate('circles')}>{manager?<><Plus size={16}/>إضافة حلقة تعليمية</>:'عرض حلقاتي'}</button></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>آخر النشاطات</h2><p>خطوات صغيرة تستحق المتابعة.</p></div><span className="mini-icon"><Clock size={17}/></span></div><div className="timeline">{data.activity.slice(0,4).map((a,i)=><div className="timeline-item" key={a.id}><span className={'timeline-dot '+(i===0?'first':'')}/><div><p>{a.message}</p><small>{a.actor_name} <span>·</span> {new Date(a.created_at).toLocaleDateString('ar-LB',{day:'numeric',month:'short'})}</small></div></div>)}</div>{!data.activity.length&&<Empty icon={Clock} title="بداية هادئة" body="يظهر هنا نشاط فريقك بعد أول خطوة."/>}<div className="activity-footer"><span className="dot"/>كلّ خطوة تُسجّل، وكلّ أثر يُرى.</div></section></div>
 <section className="panel"><div className="panel-heading"><div><h2>الحفظ والمتابعة</h2><p>آخر إنجازات طلابك تستحق أن تُروى.</p></div><button className="text-button" onClick={()=>navigate('progress')}>كل المتابعات<ArrowLeft size={15}/></button></div>{data.progress.length?<div className="table-wrap"><table><thead><tr><th>الطالب</th><th>المتابعة</th><th>التقييم</th><th>التاريخ</th></tr></thead><tbody>{data.progress.slice(0,3).map(p=><tr key={p.id}><td><strong>{p.student_name}</strong></td><td><span className="badge neutral">{p.kind}</span><span className="inline-topic">{p.topic}</span></td><td><span className={'badge '+(p.score>=4?'green':'amber')}>{SCORE[p.score]}</span></td><td className="muted">{dayLabel(p.day,true)}</td></tr>)}</tbody></table></div>:<Empty icon={GraduationCap} title="إنجازاتهم تبدأ من هنا" body="أضف أول متابعة للحفظ أو المراجعة أو الدروس."/>}</section><RanksBoard compact onOpen={()=>navigate('race')}/></>}
 {!['overview','calendar','circles','my-circles','attendance'].includes(page)&&<div className="page-heading"><div><span className="eyebrow">{admin&&page==='team'?'إدارة المنصّة · كل المساجد والمراكز':mosque?.name}</span><h1>{nav.find(n=>n[0]===page)?.[1]||({settings:'الإعدادات',mosques:'إدارة المساجد والمراكز'} as Row)[page]}</h1><p>{({students:'كل طالب، واهتمامٌ يليق برحلته.',circles:'حلقات منظّمة، وتعلّم ينمو بثبات.',team:'فريق واحد يجمعه أثر العلم.',attendance:'حضورهم خطوة أولى في رحلة التعلّم.',progress:'دوّن التقدّم، ووجّه الخطوة التالية.',reports:'أرقام تساعدك على رؤية الأثر.',settings:'مساحتك، كما تناسب جهتك وفريقك.',mosques:'مساجد ومراكز متعددة، ورسالة تعليمية واحدة.'} as Row)[page]}</p></div><div className="heading-actions">{!admin&&page==='students'&&<><button className="btn secondary" onClick={()=>exportData(true)}><Download size={16}/>تصدير</button>{!teacher&&<button className="btn primary" onClick={()=>open('student')}><Plus size={17}/>إضافة طالب</button>}</>}{!admin&&page==='circles'&&manager&&<button className="btn primary" onClick={()=>open('circle')}><Plus size={17}/>حلقة جديدة</button>}{page==='team'&&manager&&<button className="btn primary" onClick={()=>open('user')}><Plus size={17}/>إضافة حساب</button>}{!admin&&page==='progress'&&<button className="btn primary" onClick={()=>open('progress')} disabled={!activeStudents.length}><Plus size={17}/>تسجيل متابعة</button>}{page==='mosques'&&admin&&<button className="btn primary" onClick={()=>open('mosque')}><Plus size={17}/>إضافة مسجد أو مركز</button>}{!admin&&page==='reports'&&<button className="btn secondary" onClick={()=>exportData()}><Download size={16}/>تصدير بيانات الجهة</button>}</div></div>}
